const form=document.querySelector('#planForm');let plan=null;
const nowIST=()=>new Date(Date.now()+19800000).toISOString().slice(0,10);
document.querySelector('#date').min=nowIST();
for(let m=480;m<=810;m+=30){const v=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');for(const id of ['start','end']){const o=document.createElement('option');o.value=v;o.textContent=new Date('2000-01-01T'+v).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit',hour12:true});document.querySelector('#'+id).append(o);}}
document.querySelector('#end').value='13:30';
const toast=s=>{const t=document.querySelector('#toast');t.textContent=s;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,6500);};
function file(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(d.start>d.end){toast('Latest slot must be at or after the earliest slot.');return;}if(d.date<nowIST()){toast('Choose today or a future appointment date.');return;}if(d.watchStart&&new Date(d.watchStart+':00+05:30')<new Date()){toast('Choose a future checking start time, or leave it empty.');return;}plan={version:1,beneficiaryId:d.beneficiaryId.trim(),patientLabel:d.patientLabel.trim(),city:d.city.trim(),department:d.department.trim(),centre:d.centre.trim(),doctor:d.doctor.trim(),date:d.date,start:d.start,end:d.end,watchStart:d.watchStart?d.watchStart+':00+05:30':null,interval:Number(d.interval),mode:d.mode};document.querySelector('#summaryEmpty').hidden=true;const box=document.querySelector('#summary');box.hidden=false;box.replaceChildren();const dl=document.createElement('dl');const data=[['BENEFICIARY',`${plan.patientLabel||'Patient'} · ID ending ${plan.beneficiaryId.slice(-4)}`],['LOCATION',`${plan.city} · ${plan.centre}`],['DOCTOR',plan.doctor],['APPOINTMENT',`${plan.date} · ${plan.start}–${plan.end} IST`],['CHECKING',`Every ${plan.interval/60} min · ${plan.mode==='auto'?'Select & Save once':'Notify on page'}`]];for(const [label,value]of data){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;dl.append(dt,dd);}box.append(dl);document.querySelector('#planState').textContent='Plan prepared · companion not armed';document.querySelector('#planHint').textContent='Download and import the plan into your companion. This JSON includes the beneficiary ID; keep it private. No live slot check has run here.';for(const id of ['export','remind','clear'])document.querySelector('#'+id).hidden=false;toast('Your plan is ready. Import it into the browser companion to start checking.');};
document.querySelector('#export').onclick=()=>{if(plan)file('slotcare-booking-plan.json',JSON.stringify(plan,null,2),'application/json');};
document.querySelector('#remind').onclick=()=>{if(!plan)return;const d=plan.watchStart?new Date(plan.watchStart):new Date(Date.now()+300000);const start=d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const end=new Date(d.getTime()+10*60000).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');file('slotcare-check-reminder.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//SlotCare//Appointment reminder//EN','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@slotcare','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+start,'DTEND:'+end,'SUMMARY:Open CGHS and start SlotCare checking','DESCRIPTION:Sign in on the official CGHS portal and arm your browser companion. This is a reminder only; no appointment is booked.','BEGIN:VALARM','TRIGGER:-PT5M','ACTION:DISPLAY','DESCRIPTION:Open CGHS for SlotCare','END:VALARM','END:VEVENT','END:VCALENDAR',''].join('\r\n'),'text/calendar');toast('Import this reminder into your calendar. It does not book an appointment.');};
document.querySelector('#clear').onclick=()=>{plan=null;document.querySelector('#beneficiaryId').value='';form.elements.patientLabel.value='';document.querySelector('#summary').hidden=true;document.querySelector('#summaryEmpty').hidden=false;document.querySelector('#planState').textContent='No active live checking';document.querySelector('#planHint').textContent='Preparing a plan does not book an appointment. The companion must be armed on CGHS.';for(const id of ['export','remind','clear'])document.querySelector('#'+id).hidden=true;toast('Plan cleared from this page. Delete any downloaded plan file separately.');};
